-- GENERATED by `wfj generate` from data/gossip/gossip-0e.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["0e09682a9d7e0588"] = { "Nei giorni ormai lontani vivevamo per la caccia. Cacciavamo per la gloria, per l'onore...\n\nÈ poi così diverso adesso?", "." },
  ["0e1126b186478fd1"] = { "Il ⟦Stonehearth Graveyard=Cimitero di Cordipietra⟧ è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo conquisterà!", "." },
  ["0e12a96b266f6a1e"] = { "Ah, vedo che hai già padroneggiato la forma d'orso. Bene, bene. Sei sulla buona strada, giovane {class}.", "." },
  ["0e212e971f698feb"] = { "Hai l'aria di chi ha il cuore spezzato. Torna quando non sarai così triste.", "." },
  ["0e21745b22f6d6b9"] = { "Le nostre forze sono pronte e impazienti. Presto Balinda Stonehearth entrerà nel suo avamposto e la battaglia ricomincerà!", "." },
  ["0e23ae1d11138d9b"] = { "Non sbucare dall'ombra in quel modo. La prossima volta dai un po' di preavviso a una ragazza.", "." },
  ["0e2f090b78e87115"] = { "L'⟦Alliance=Alleanza⟧ ci ha abbandonati!", "." },
  ["0e31b5b56941cf12"] = { "La cucina è una passione di tutta una vita, e vedo che la condividiamo!", "." },
  ["0e31d285ba2300b3"] = { "Sì, l'ho fatto. Con grande sgomento del Mograine minore, tornai al ⟦Scarlet Monastery=Monastero Scarlatto⟧. Urlai e gridai. Raccontai la storia a chiunque volesse ascoltare. E per questo mi avrebbero assassinato a sangue freddo e trascinato in questa stanza, l'oscuro segreto dell'ordine. Ma alcuni ascoltarono... alcuni udirono le mie parole. Così nacque l'⟦Argent Dawn=Alba d'Argento⟧...", "." },
  ["0e41fea460c34d27"] = { "Il ⟦Ragefire Chasm=Baratro di Fiamma Furente⟧ è una rete di caverne vulcaniche sotto la nuova capitale degli orchi, Orgrimmar. Di recente si è sparsa la voce che un culto fedele al demoniaco ⟦Shadow Council=Concilio dell'Ombra⟧ si sia stabilito nelle profondità infuocate del Baratro. Questo culto, noto come ⟦Burning Blade=Lame Ardenti⟧, minaccia la sovranità stessa di Durotar. Molti credono che il Capoguerra degli orchi, Thrall, sia a conoscenza dell'esistenza delle ⟦Burning Blade=Lame Ardenti⟧ e abbia scelto di non distruggerle nella speranza che i loro membri lo conducano dritto al ⟦Shadow Council=Concilio dell'Ombra⟧.", "." },
  ["0e50b507a9c6aced"] = { "Ehi! Via dal nostro tesoro!", "." },
  ["0e560f4eda449a83"] = { "Invasori, cessate subito questa folle impresa! Tornate indietro finché potete!", "." },
  ["0e63ffdcd671c0cf"] = { "Be', vado fuori a controllare. C'è qualcosa che non va.", "." },
  ["0e68ab94ea80d62c"] = { "Massacrateli nel nome del padrone!", "." },
  ["0e6b07ab0fcac51d"] = { "L'anziano Barbabronzea si trova a ⟦Ironforge=Forgiardente⟧, la dimora ancestrale dei Bronzebeard.", "." },
  ["0e74d0bfb73b4136"] = { "Aaahhh... Un'altra gloriosa vittoria per l'⟦Horde=Orda⟧!", "." },
  ["0e751740f689b1db"] = { "Oh, lo farò, amico mio. Lo farò senz'altro. Abbi cura di te anche tu.", "." },
  ["0e87d25f5c43a30d"] = { "I Sabbiafurente regnano supremi!", "." },
  ["0e88a2ffae0bf6f3"] = { "Ah, la libertà dal terribile incubo! Ti ringrazio, mio fedele Discepolo, insieme ai tuoi coraggiosi compagni.", "." },
  ["0e895246a20cfcee"] = { "Vivranno, se non altro per vedere i frutti del loro lavoro: la distruzione e il caos che di certo seguiranno quando la legione di ⟦Blackrock=Roccianera⟧ invaderà la gola.", "." },
  ["0e8c646a9b87bf90"] = { "Con parte della tecnologia recuperata dagli gnomi audaci che si sono avventurati a Gnomeregan, ho potuto costruire la mia più grande invenzione: il Matter Transporter! Ora mi serve solo un abile esperto di ⟦Gnomish Engineer=Ingegneria degli Gnomi⟧ che costruisca un potente faro sintonizzato con il trasportatore.", "." },
  ["0e8df91244902a65"] = { "{name}! <Traditore/Traditrice> di Ragnaros!", "." },
  ["0e91a8b0419ef8c5"] = { "⟦Icy Scale Breastplate=Pettorale Corazzato di Scaglie Ghiacciate⟧.", "." },
  ["0e9306367f67a11c"] = { "Anche i maghi? Dovresti fare più attenzione quando giochi con la magia...", "." },
  ["0e93767324a83e03"] = { "Compra qualcosa, eh?", "." },
  ["0e94f6efb467a0c6"] = { "Non volevo trascinarti in questa storia, {name}. Da quando abbiamo accettato l'incarico di rubare il libro degli incantesimi di lord Valthalak, tutti quelli coinvolti sono finiti morti o dispersi.", "." },
  ["0e999ea49abf2446"] = { "Guarda dove metti i piedi, soldato. I Piccatonante hanno disseminato di mine il terreno attorno alle loro basi. Parla con il nostro esperto di esplosivi nella torre di guardia a est se vuoi sapere come disinnescare i loro campi minati.", "." },
  ["0ea05be73aa7dbc8"] = { "Sì, <signore/signora>.", "." },
  ["0ea074d534700f6d"] = { "È stata Umi, vero?! Mi fa sempre degli scherzi, e adesso ha coinvolto anche te!", "." },
  ["0eb68d879913d268"] = { "A rapporto, signore.", "." },
  ["0eba01db03d176cd"] = { "Le colonne di questo santuario sono per me come le sbarre di una prigione, {name}. Nessuna forza che ancora possiedo potrebbe spezzarle, e nessuna magia che padroneggio potrebbe distruggerle...\n\nPer più di mille anni le ho fissate, chiedendomi se, sopravvivendo infine persino alla pietra, sarei stato libero. O se allora mi avrebbero trattenuto sbarre invisibili...", "." },
  ["0ebba580eabd7ca1"] = { "Appena arrivato... un altro lotto di ⟦Darkmoon Special Reserve=Riserva Speciale di Lunacupa⟧. Vieni a prendere la tua prima che finisca!", "." },
  ["0eca375e9832e401"] = { "MORIRE?! Tu fai piangere Pusillin!", "." },
  ["0ecac1cf1b373eb5"] = { "Se ricordi una sola cosa, sappi questo: nemmeno la morte può fermare la Luce.\r\n\nQuesto lo abbiamo in comune con tutti i Reietti: abbiamo superato ciò che i vivi considerano la propria fine. Eppure alcuni, anche tra i nostri, ci temono; sospettano che li colpiremo come una qualche mostruosità.\r\n\nIn verità, il nostro rapporto con la non morte è complesso, ma non siamo qui per fare del male ai nostri. Aiutami a dimostrarlo agli altri. Avventurati nella Valle Telanera, a nord-ovest, e libera gli sciocchi appena risorti intrappolati dai ragni.\r\n\nAllora vedranno la nostra natura.", "." },
  ["0ecdff26e0399c02"] = { "Mi pare di aver visto arrivare una nuova spedizione di posta non molto tempo fa. Troverai la cassetta postale appena fuori dalla Banca di ⟦Thunder Bluff=Picco del Tuono⟧, sull'altura inferiore.", "." },
  ["0ed841a149622da7"] = { "Grazie per avermi aiutato. Da qui conosco la strada.", "." },
  ["0edc101af75766bd"] = { "Hai trovato prove sul luogo della ⟦Shady Rest Inn=Locanda Ombracalma⟧?", "." },
  ["0edead8039ca1667"] = { "Stai in guardia, {name}!", "." },
  ["0ee1dc59a551b570"] = { "Un caposaldo della ⟦Thorium Brotherhood=Fratellanza del Torio⟧.\n\nI cristalli d'arcanite si estraggono da ricchi filoni di torio. Grazie all'abilità di potenti alchimisti, nascono i Lingotti d'Arcanite.\n\nCerca un minatore, se non lo sei... e trova un buon alchimista! Ti serviranno entrambi.", "." },
  ["0ee4efaa2a2e9e69"] = { "Il buon dottore salva la situazione! URRÀ!", "." },
  ["0ee6d6682fe61ba1"] = { "Se il tuo forte è la sartoria, Vizzklick avrà di sicuro quello che ti serve. Dai un'occhiata in giro, {name}, e fammi sapere se vuoi comprare qualcosa!", "." },
  ["0ee740c901b3eed8"] = { "Aiutatemi a uccidere {name}!", "." },
  ["0ee8a9b28be7e2a5"] = { "Dobbiamo muoverci in fretta. Auberdine non è troppo lontana, ma nella foresta si annidano molti nemici.", "." },
  ["0efb602a50dc5880"] = { "È giunta la tua ora, {name}. Il maestro Kang ti aspetta...", "." },
})
